"""Weighted graph data structure with shortest path computation."""

import heapq
from collections import defaultdict


class WeightedGraph:
    """Undirected weighted graph supporting bandwidth, delay, and loss attributes on edges."""

    def __init__(self):
        self._adj = defaultdict(dict)
        self._nodes = set()

    def add_node(self, name):
        self._nodes.add(name)

    def add_edge(self, u, v, **attrs):
        self._nodes.add(u)
        self._nodes.add(v)
        self._adj[u][v] = attrs
        self._adj[v][u] = attrs

    def remove_edge(self, u, v):
        self._adj[u].pop(v, None)
        self._adj[v].pop(u, None)

    def neighbors(self, u):
        return list(self._adj[u].keys())

    def get_edge(self, u, v):
        return self._adj[u].get(v, {})

    def has_edge(self, u, v):
        return v in self._adj[u]

    @property
    def nodes(self):
        return list(self._nodes)

    def shortest_path(self, src, dst):
        """Dijkstra shortest path by hop count. Returns list of nodes or None."""
        if src == dst:
            return [src]
        if src not in self._nodes or dst not in self._nodes:
            return None

        dist = {src: 0}
        prev = {src: None}
        pq = [(0, src)]
        visited = set()

        while pq:
            d, u = heapq.heappop(pq)
            if u in visited:
                continue
            visited.add(u)
            if u == dst:
                break
            for v in self._adj[u]:
                if v not in visited:
                    nd = d + 1
                    if v not in dist or nd < dist[v]:
                        dist[v] = nd
                        prev[v] = u
                        heapq.heappush(pq, (nd, v))

        if dst not in prev:
            return None
        path = []
        cur = dst
        while cur is not None:
            path.append(cur)
            cur = prev[cur]
        path.reverse()
        return path

    def all_pairs_shortest_paths(self, node_subset=None):
        """Return dict of (src, dst) -> path for all pairs in node_subset."""
        nodes = node_subset if node_subset else list(self._nodes)
        result = {}
        for src in nodes:
            for dst in nodes:
                if src != dst:
                    p = self.shortest_path(src, dst)
                    if p:
                        result[(src, dst)] = p
        return result

"""Utility functions for network simulation."""

import math


def generate_ip(index, base="10.0"):
    """Generate an IP address from a host index."""
    subnet = index // 254
    host = (index % 254) + 1
    return f"{base}.{subnet}.{host}"


def compute_bottleneck_bw(bandwidths):
    """Compute bottleneck bandwidth along a path (minimum of link bandwidths)."""
    if not bandwidths:
        return 0.0
    return min(bandwidths)


def compute_path_delay(delays):
    """Compute one-way delay along a path (sum of link delays)."""
    return sum(delays)


def compute_path_loss_rate(loss_rates):
    """Compute end-to-end loss probability from per-link loss rates (0-1 scale)."""
    success = 1.0
    for lr in loss_rates:
        success *= (1.0 - lr)
    return 1.0 - success


def dbm_to_mw(dbm):
    """Convert dBm to milliwatts."""
    return 10.0 ** (dbm / 10.0)


def mw_to_dbm(mw):
    """Convert milliwatts to dBm."""
    if mw <= 0:
        return -float('inf')
    return 10.0 * math.log10(mw)


def distance_2d(pos1, pos2):
    """Euclidean distance between two 2D points."""
    return math.sqrt((pos1[0] - pos2[0]) ** 2 + (pos1[1] - pos2[1]) ** 2)


def jains_fairness_index(allocations):
    """Compute Jain's fairness index for a list of allocations."""
    if not allocations or all(a == 0 for a in allocations):
        return 0.0
    n = len(allocations)
    sum_x = sum(allocations)
    sum_x2 = sum(x * x for x in allocations)
    return (sum_x ** 2) / (n * sum_x2)

"""Packet model for network simulation."""

from dataclasses import dataclass, field
from typing import List, Optional


@dataclass
class Packet:
    """A network packet traversing the simulated topology."""
    src_ip: str
    dst_ip: str
    size_bytes: int = 1500
    protocol: str = "ICMP"
    ttl: int = 64


@dataclass
class PacketTrace:
    """Records the path a packet takes through the network."""
    packet: Packet
    hops: List[str] = field(default_factory=list)
    total_delay_ms: float = 0.0
    delivered: bool = False

    def add_hop(self, node_name: str, delay_ms: float = 0.0):
        self.hops.append(node_name)
        self.total_delay_ms += delay_ms

    @property
    def hop_count(self):
        return max(0, len(self.hops) - 1)

