"""Node abstractions for the simulated network.

Mirrors the Mininet node hierarchy (Lantz et al., HotNets 2010): every element of
the emulated network is a ``Node``; hosts, switches and controllers specialise it.
"""


class Node:
    """Base class for anything that can terminate a link.

    A node owns a set of interfaces keyed by port number and carries an
    arbitrary parameter dictionary (the emulated equivalent of the options a
    real Mininet node would pass down to the network namespace).
    """

    #: Set on container-backed nodes (see :mod:`netsim.container`).
    is_container = False

    def __init__(self, name, ip=None, **params):
        self.name = name
        self.params = dict(params)
        self.intfs = {}
        self.ip = ip if ip is not None else params.get("ip")

    # -- interface management ------------------------------------------------
    def addIntf(self, intf, port=None):
        """Attach ``intf`` to this node, returning the port it landed on."""
        if port is None:
            port = self.newPort()
        self.intfs[port] = intf
        intf.node = self
        intf.port = port
        return port

    def newPort(self):
        """Return the next free port number (ports start at 0, as in Mininet)."""
        if not self.intfs:
            return 0
        return max(self.intfs.keys()) + 1

    def ports(self):
        return sorted(self.intfs.keys())

    def interfaces(self):
        return [self.intfs[p] for p in self.ports()]

    def connectionsTo(self, other):
        """Return [(local intf, remote intf)] for every link to ``other``."""
        result = []
        for intf in self.interfaces():
            link = intf.link
            if link is None:
                continue
            peer = link.peer_intf(intf)
            if peer is not None and peer.node is other:
                result.append((intf, peer))
        return result

    def links(self):
        seen = []
        for intf in self.interfaces():
            if intf.link is not None and intf.link not in seen:
                seen.append(intf.link)
        return seen

    def setIP(self, ip):
        self.ip = ip
        return ip

    def IP(self):
        return self.ip

    # -- lifecycle ----------------------------------------------------------
    def start(self, *args, **kwargs):
        """Hook for subclasses; the simulation has nothing to launch."""
        return None

    def stop(self, *args, **kwargs):
        return None

    def __repr__(self):
        return "<%s %s>" % (type(self).__name__, self.name)

    def __str__(self):
        return self.name


class Host(Node):
    """An emulated end host."""

    #: Simulated time (ms) needed to bring a namespace-based host up.
    HOST_STARTUP_MS = 10.0

    def __init__(self, name, ip=None, **params):
        Node.__init__(self, name, ip=ip, **params)

    @property
    def startup_time_ms(self):
        return self.HOST_STARTUP_MS


class Switch(Node):
    """An OpenFlow-capable switch.

    ``FORWARDING_OVERHEAD`` models the throughput cost of traversing one switch
    (2% per hop); the simulation engine applies it once per switch on a path.
    """

    FORWARDING_OVERHEAD = 0.02

    def __init__(self, name, dpid=None, **params):
        Node.__init__(self, name, **params)
        self.dpid = dpid if dpid is not None else self._default_dpid(name)
        self.controllers = []

    @staticmethod
    def _default_dpid(name):
        digits = "".join(ch for ch in name if ch.isdigit())
        return "%016x" % int(digits or 0)

    @property
    def forwarding_overhead(self):
        return self.FORWARDING_OVERHEAD

    @property
    def throughput_factor(self):
        """Fraction of offered load that survives one switch hop."""
        return 1.0 - self.FORWARDING_OVERHEAD

    def attach_controller(self, controller):
        if controller not in self.controllers:
            self.controllers.append(controller)
        return controller


class OVSSwitch(Switch):
    """Open vSwitch flavoured switch (the Mininet default)."""

    def __init__(self, name, dpid=None, failMode="secure", datapath="kernel",
                 **params):
        Switch.__init__(self, name, dpid=dpid, **params)
        self.failMode = failMode
        self.datapath = datapath


class Controller(Node):
    """An SDN controller reachable by the switches of the network."""

    def __init__(self, name, ip="127.0.0.1", port=6653, **params):
        Node.__init__(self, name, ip=ip, **params)
        self.port = port
        self.switches = []

    def register(self, switch):
        if switch not in self.switches:
            self.switches.append(switch)
        switch.attach_controller(self)
        return switch

