"""Access points: switches with a radio."""

from ..node import Switch
from ..utils import distance_2d
from .propagation import (DEFAULT_PATH_LOSS_EXP, DEFAULT_REF_DISTANCE_M,
                          ghz_to_hz, max_range, received_signal_strength)


class AccessPoint(Switch):
    """A WiFi access point; a switch that stations can associate with."""

    def __init__(self, name, position=(0.0, 0.0), ssid=None, channel=1,
                 tx_power_dbm=20.0, freq_ghz=2.4,
                 path_loss_exp=DEFAULT_PATH_LOSS_EXP,
                 ref_distance_m=DEFAULT_REF_DISTANCE_M,
                 min_rssi_dbm=-80.0, mode="g", antenna_gain_dbi=0.0,
                 **params):
        Switch.__init__(self, name, **params)
        self.position = tuple(float(c) for c in position)
        self.ssid = ssid if ssid is not None else "%s-ssid" % name
        self.channel = channel
        self.tx_power_dbm = float(tx_power_dbm)
        self.freq_ghz = float(freq_ghz)
        self.path_loss_exp = float(path_loss_exp)
        self.ref_distance_m = float(ref_distance_m)
        self.min_rssi_dbm = float(min_rssi_dbm)
        self.mode = mode
        self.antenna_gain_dbi = float(antenna_gain_dbi)
        self.associated_stations = []

    # -- radio --------------------------------------------------------------
    @property
    def freq_hz(self):
        return ghz_to_hz(self.freq_ghz)

    def set_position(self, position):
        self.position = tuple(float(c) for c in position)
        return self.position

    def distance_to(self, other):
        pos = getattr(other, "position", other)
        return distance_2d(self.position, pos)

    def rssi_at(self, position, rx_gain_dbi=0.0):
        """RSSI (dBm) a receiver at ``position`` would measure."""
        return received_signal_strength(
            self.tx_power_dbm, self.freq_hz, self.distance_to(position),
            path_loss_exp=self.path_loss_exp,
            ref_distance_m=self.ref_distance_m,
            tx_gain_dbi=self.antenna_gain_dbi, rx_gain_dbi=rx_gain_dbi)

    @property
    def range_m(self):
        """Maximum distance at which the RSSI still exceeds ``min_rssi_dbm``."""
        return max_range(self.tx_power_dbm, self.min_rssi_dbm, self.freq_hz,
                         path_loss_exp=self.path_loss_exp,
                         ref_distance_m=self.ref_distance_m,
                         tx_gain_dbi=self.antenna_gain_dbi)

    def in_range(self, position, rx_gain_dbi=0.0):
        return self.rssi_at(position, rx_gain_dbi=rx_gain_dbi) >= \
            self.min_rssi_dbm

    # -- association --------------------------------------------------------
    def associate(self, station):
        if station not in self.associated_stations:
            self.associated_stations.append(station)
        return station

    def disassociate(self, station):
        if station in self.associated_stations:
            self.associated_stations.remove(station)
        return station

    def count_stations(self):
        return len(self.associated_stations)

    def __repr__(self):
        return "<AccessPoint %s ssid=%s pos=%s>" % (
            self.name, self.ssid, self.position)

